if old in content:
    content = content.replace(old, new)
    with open(path, 'w', encoding='utf-8') as f:
        f.write(content)
    print("SUCCESS - dark theme applied to menu.html!")
else:
    print("ERROR - could not find the style block to replace")
    print("Trying line by line search...")
    for i, line in enumerate(content.split("\n")[:30], 1):
        print(f"  {i}: {repr(line)}")
